1	syntax = "proto3";
2	
3	package memos.store;
4	
5	import "google/protobuf/timestamp.proto";
6	import "store/instance_setting.proto";
7	
8	option go_package = "gen/store";
9	
10	enum AttachmentStorageType {
11	  ATTACHMENT_STORAGE_TYPE_UNSPECIFIED = 0;
12	  // Attachment is stored locally. AKA, local file system.
13	  LOCAL = 1;
14	  // Attachment is stored in S3.
15	  S3 = 2;
16	  // Attachment is stored in an external storage. The reference is a URL.
17	  EXTERNAL = 3;
18	}
19	
20	enum MotionMediaFamily {
21	  MOTION_MEDIA_FAMILY_UNSPECIFIED = 0;
22	  APPLE_LIVE_PHOTO = 1;
23	  ANDROID_MOTION_PHOTO = 2;
24	}
25	
26	enum MotionMediaRole {
27	  MOTION_MEDIA_ROLE_UNSPECIFIED = 0;
28	  STILL = 1;
29	  VIDEO = 2;
30	  CONTAINER = 3;
31	}
32	
33	message MotionMedia {
34	  MotionMediaFamily family = 1;
35	  MotionMediaRole role = 2;
36	  string group_id = 3;
37	  int64 presentation_timestamp_us = 4;
38	  bool has_embedded_video = 5;
39	}
40	
41	message AttachmentPayload {
42	  oneof payload {
43	    S3Object s3_object = 1;
44	  }
45	
46	  MotionMedia motion_media = 10;
47	
48	  message S3Object {
49	    StorageS3Config s3_config = 1;
50	    // key is the S3 object key.
51	    string key = 2;
52	    // last_presigned_time is the last time the object was presigned.
53	    // This is used to determine if the presigned URL is still valid.
54	    google.protobuf.Timestamp last_presigned_time = 3;
55	  }
56	}
